<script lang="ts">
  import { onMount } from 'svelte';
  import { api } from '$lib/api';

  type PortalStudent = { studentId: number; displayName: string; rankName?: string; ageGroup?: string; isActive: boolean; status: 'active' | 'paused' | 'deactivated'; joinDate?: string; uniformSize?: string; beltSize?: string; bio?: string; favoriteTechnique?: string; totalClasses: number; attendanceStreak: number; achievementCount: number; goldStarCount: number; programs: string[] };
  type StudentForm = { firstName: string; lastName: string; preferredName: string; ageGroup: string; joinDate: string; uniformSize: string; beltSize: string; bio: string; favoriteTechnique: string };
  const blankForm = (): StudentForm => ({ firstName: '', lastName: '', preferredName: '', ageGroup: 'Kids', joinDate: new Date().toISOString().slice(0, 10), uniformSize: '', beltSize: '', bio: '', favoriteTechnique: '' });
  let students: PortalStudent[] = [];
  let form = blankForm();
  let editingId = '';
  let statusFilter: 'active' | 'paused' | 'deactivated' | 'all' = 'active';
  let query = '';
  let page = 1;
  const pageSize = 25;
  let error = '';
  let notice = '';
  let loading = true;
  let saving = false;
  let resettingPassword = false;
  let passwordForm = { password: '', confirmPassword: '' };

  async function load() { loading = true; error = ''; try { students = await api<PortalStudent[]>('/api/portal-admin/students'); } catch (e) { error = e instanceof Error ? e.message : 'Could not load portal students.'; } finally { loading = false; } }
  $: visibleStudents = students.filter((student) => (statusFilter === 'all' || student.status === statusFilter) && `${student.displayName} ${student.rankName ?? ''} ${student.programs.join(' ')}`.toLowerCase().includes(query.trim().toLowerCase()));
  $: pageCount = Math.max(1, Math.ceil(visibleStudents.length / pageSize));
  $: if (page > pageCount) page = pageCount;
  $: pagedStudents = visibleStudents.slice((page - 1) * pageSize, page * pageSize);
  function resetPage() { page = 1; }
  function previousPage() { if (page > 1) page -= 1; }
  function nextPage() { if (page < pageCount) page += 1; }
  function resetForm() { form = blankForm(); editingId = ''; }
  function edit(student: PortalStudent) { editingId = String(student.studentId); const parts = student.displayName.split(' '); form = { ...blankForm(), firstName: parts.shift() ?? '', lastName: parts.join(' '), preferredName: student.displayName, ageGroup: student.ageGroup === 'TeensAdults' ? 'TeensAdults' : 'Kids', joinDate: student.joinDate?.slice(0, 10) ?? blankForm().joinDate, uniformSize: student.uniformSize ?? '', beltSize: student.beltSize ?? '', bio: student.bio ?? '', favoriteTechnique: student.favoriteTechnique ?? '' }; window.scrollTo({ top: 0, behavior: 'smooth' }); }
  async function save() { error = ''; notice = ''; saving = true; try { const payload = { ...form, joinDate: form.joinDate || null }; if (editingId) { await api(`/api/portal-admin/students/${editingId}`, { method: 'PUT', body: JSON.stringify(payload) }); notice = 'Student profile updated in the portal database.'; } else { await api('/api/portal-admin/students', { method: 'POST', body: JSON.stringify(payload) }); notice = 'Portal student created.'; } resetForm(); await load(); } catch (e) { error = e instanceof Error ? e.message : 'Could not save student.'; } finally { saving = false; } }
  async function setStatus(student: PortalStudent, status: 'active' | 'paused' | 'deactivated') { error = ''; try { await api(`/api/portal-admin/students/${student.studentId}/status`, { method: 'POST', body: JSON.stringify({ status }) }); notice = `${student.displayName} marked ${status}.`; await load(); } catch (e) { error = e instanceof Error ? e.message : 'Could not update student status.'; } }
  async function resetPassword() { if (!editingId) return; error = ''; notice = ''; resettingPassword = true; try { const result = await api<{ username: string }>(`/api/portal-admin/students/${editingId}/password`, { method: 'POST', body: JSON.stringify(passwordForm) }); passwordForm = { password: '', confirmPassword: '' }; notice = `Student PIN changed. Account username: ${result.username}`; } catch (e) { error = e instanceof Error ? e.message : 'Could not change the student PIN.'; } finally { resettingPassword = false; } }
  onMount(load);
</script>

<svelte:head><title>Staff · Students | Task Karate</title></svelte:head>
<div class="toolbar"><div><span class="eyebrow">PORTAL PEOPLE</span><h2>Student profiles</h2><p class="muted">This roster reads and writes the same database used by the student hub. Changes are audited.</p></div></div>
{#if error}<div class="error" role="alert">{error}</div>{/if}{#if notice}<div class="status" role="status">{notice}</div>{/if}
<section class="card"><div class="section-heading"><div><h3>{editingId ? 'Edit portal profile' : 'Create portal student'}</h3><p class="muted">Keep private notes appropriate for staff use. Passwords are managed separately through the secure account workflow.</p></div>{#if editingId}<button class="button secondary small-button" type="button" on:click={resetForm}>Cancel edit</button>{/if}</div><form class="form-grid" on:submit|preventDefault={save}><label>First name<input bind:value={form.firstName} required /></label><label>Last name<input bind:value={form.lastName} required /></label><label>Display name<input bind:value={form.preferredName} placeholder="Shown to students" /></label><label>Age group<select bind:value={form.ageGroup}><option value="Kids">Kids</option><option value="TeensAdults">Teens & Adults</option></select></label><label>Join date<input type="date" bind:value={form.joinDate} required /></label><label>Uniform size<input bind:value={form.uniformSize} /></label><label>Belt size<input bind:value={form.beltSize} /></label><label>Favorite technique<input bind:value={form.favoriteTechnique} /></label><label class="full">Profile note<textarea bind:value={form.bio} maxlength="1000"></textarea></label><div class="full"><button class="button" disabled={saving}>{saving ? 'Saving…' : editingId ? 'Save profile changes' : 'Create portal student'}</button></div></form></section>
{#if editingId}<section class="card password-admin-card"><div class="section-heading"><div><h3>Reset student PIN</h3><p class="muted">Administrator-only reset. Students use a 4–6 digit PIN; the existing PIN is never shown.</p></div></div><form class="form-grid" on:submit|preventDefault={resetPassword}><label>New PIN<input type="password" bind:value={passwordForm.password} minlength="4" maxlength="6" pattern="[0-9][0-9][0-9][0-9][0-9]?[0-9]?" autocomplete="new-password" required /><small class="muted">Use 4–6 digits. Share it through a supervised channel.</small></label><label>Confirm new PIN<input type="password" bind:value={passwordForm.confirmPassword} minlength="4" maxlength="6" pattern="[0-9][0-9][0-9][0-9][0-9]?[0-9]?" autocomplete="new-password" required /></label><div class="full"><button class="button" disabled={resettingPassword}>{resettingPassword ? 'Changing…' : 'Change student PIN'}</button></div></form></section>{/if}
<section class="card"><div class="section-heading"><div><h3>{statusFilter === 'all' ? 'All portal records' : `${statusFilter[0].toUpperCase()}${statusFilter.slice(1)} portal roster`}</h3><span class="pill">{visibleStudents.length}</span></div><div class="staff-list-controls"><input bind:value={query} on:input={resetPage} type="search" placeholder="Search portal students…" aria-label="Search portal students" /><label>Status<select bind:value={statusFilter} on:change={resetPage}><option value="active">Active</option><option value="paused">Paused</option><option value="deactivated">Deactivated</option><option value="all">All statuses</option></select></label></div></div><p class="muted roster-help">Active students can be enrolled and checked in. Paused students remain in the portal directory but are hidden from attendance pickers. Deactivated records are retained for history.</p>{#if loading}<p class="muted">Loading portal database…</p>{:else}<div class="table-wrap"><table><thead><tr><th>Student</th><th>Programs</th><th>Classes</th><th>Recognition</th><th>Status</th><th>Actions</th></tr></thead><tbody>{#each pagedStudents as student}<tr><td><strong>{student.displayName}</strong><small class="table-subtext">{student.rankName ?? 'Rank not assigned'} · {student.ageGroup ?? 'Age group not set'}</small></td><td>{student.programs.join(', ') || 'No program'}</td><td>{student.totalClasses} · {student.attendanceStreak} day streak</td><td>{student.achievementCount} achievements · {student.goldStarCount} Gold Stars</td><td><span class="pill student-status-pill {student.status}">{student.status === 'active' ? 'Active' : student.status === 'paused' ? 'Paused' : 'Deactivated'}</span></td><td><div class="table-actions"><button class="button secondary small-button" type="button" on:click={() => edit(student)}>Edit profile</button>{#if student.status === 'active'}<button class="button secondary small-button" type="button" on:click={() => setStatus(student, 'paused')}>Pause student</button><button class="button danger small-button" type="button" on:click={() => setStatus(student, 'deactivated')}>Deactivate</button>{:else if student.status === 'paused'}<button class="button secondary small-button" type="button" on:click={() => setStatus(student, 'active')}>Resume student</button><button class="button danger small-button" type="button" on:click={() => setStatus(student, 'deactivated')}>Deactivate</button>{:else}<button class="button secondary small-button" type="button" on:click={() => setStatus(student, 'active')}>Reactivate</button>{/if}</div></td></tr>{:else}<tr><td colspan="6" class="muted">No portal students match this view.</td></tr>{/each}</tbody></table></div><div class="pagination" aria-label="Student roster pages"><button class="button secondary small-button" type="button" disabled={page <= 1} on:click={previousPage}>Previous</button><span>Page {page} of {pageCount}</span><button class="button secondary small-button" type="button" disabled={page >= pageCount} on:click={nextPage}>Next</button></div>{/if}</section>
